package com.b5.shared;
import android.content.*;import android.provider.Settings;import com.google.firebase.*;import com.google.firebase.auth.*;import com.google.firebase.database.*;import org.json.*;import java.io.*;import java.util.*;
public final class Cloud {
 public final FirebaseAuth auth;public final FirebaseDatabase db;public final DatabaseReference root;private long anchorWall=System.currentTimeMillis(),anchorElapsed=android.os.SystemClock.elapsedRealtime();public long offset=0;public boolean clockReady=false,online=false;public final String deviceId;private final Context ctx;
 public interface Done{void run();}public interface Fail{void run(String message);}
 public Cloud(Context c){ctx=c.getApplicationContext();JSONObject j=config(c);FirebaseApp app;try{app=FirebaseApp.getInstance();}catch(IllegalStateException e){FirebaseOptions o=new FirebaseOptions.Builder().setProjectId(j.optString("projectId")).setApiKey(j.optString("apiKey")).setApplicationId(j.optString("applicationId")).setDatabaseUrl(j.optString("databaseUrl")).build();app=FirebaseApp.initializeApp(c,o);}auth=FirebaseAuth.getInstance(app);db=FirebaseDatabase.getInstance(app,j.optString("databaseUrl"));root=db.getReference();deviceId=Settings.Secure.getString(c.getContentResolver(),Settings.Secure.ANDROID_ID);root.child(".info/connected").addValueEventListener(listener(s->{online=Boolean.TRUE.equals(s.getValue(Boolean.class));},m->{}));root.child(".info/serverTimeOffset").addValueEventListener(listener(s->{Long x=s.getValue(Long.class);offset=x==null?0:x;anchorWall=System.currentTimeMillis()+offset;anchorElapsed=android.os.SystemClock.elapsedRealtime();clockReady=true;},m->{}));}
 public static String read(InputStream in)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toString("UTF-8");}
 public long now(){return anchorWall+android.os.SystemClock.elapsedRealtime()-anchorElapsed;}
 public static JSONObject config(Context c){try{String s=c.getSharedPreferences("b5",0).getString("firebase",null);if(s==null)try(InputStream in=c.getAssets().open("firebase-config.json")){s=read(in);}return new JSONObject(s);}catch(Exception e){return new JSONObject();}}
 public static boolean configured(Context c){JSONObject j=config(c);return !j.optString("apiKey").isEmpty()&&j.optString("databaseUrl").startsWith("https://")&&!j.optString("projectId").isEmpty()&&!j.optString("applicationId").isEmpty();}
 public static void setup(BrandActivity a,Runnable done){a.page("Connect Firebase","One shared project. No external application server.");android.widget.LinearLayout card=a.card();JSONObject old=config(a);String[] keys={"projectId","databaseUrl","apiKey","applicationId"};String[] hints={"Firebase Project ID","Realtime Database HTTPS URL","Firebase Web API key (public config)","Firebase Android Application ID"};android.widget.EditText[] e=new android.widget.EditText[4];for(int i=0;i<4;i++){e[i]=a.input(card,hints[i],false);e[i].setText(old.optString(keys[i]));}a.note(card,"Enable Anonymous and Email/Password authentication. Deploy database.rules.json first. These are public Firebase identifiers, not service-account credentials.");a.button(card,"Save Firebase settings",()->{try{JSONObject j=new JSONObject();for(int i=0;i<4;i++){String s=e[i].getText().toString().trim();if(s.isEmpty())throw new Exception("Complete all fields");j.put(keys[i],s);}java.net.URI u=new java.net.URI(j.getString("databaseUrl"));String host=u.getHost();if(!"https".equals(u.getScheme())||host==null||!(host.endsWith(".firebaseio.com")||host.endsWith(".firebasedatabase.app")))throw new Exception("Use your Firebase Realtime Database HTTPS URL");a.getSharedPreferences("b5",0).edit().putString("firebase",j.toString()).apply();done.run();}catch(Exception x){a.message(x.getMessage());}});a.footer();}
 public void anonymous(Done done,Fail fail){if(auth.getCurrentUser()!=null){done.run();return;}auth.signInAnonymously().addOnSuccessListener(r->done.run()).addOnFailureListener(e->fail.run(e.getMessage()));}
 public interface Read{void run(DataSnapshot s);}public static ValueEventListener listener(Read r,Fail f){return new ValueEventListener(){public void onDataChange(DataSnapshot s){r.run(s);}public void onCancelled(DatabaseError e){f.run(e.getMessage());}};}
 public static long num(DataSnapshot s,String key){Long n=s.child(key).getValue(Long.class);return n==null?0:n;}public static String str(DataSnapshot s,String k){String v=s.child(k).getValue(String.class);return v==null?"":v;}public static boolean yes(DataSnapshot s,String k){return Boolean.TRUE.equals(s.child(k).getValue(Boolean.class));}
 public void socials(BrandActivity a,android.widget.LinearLayout container){root.child("config/socials").get().addOnSuccessListener(s->{for(String k:new String[]{"tiktok","instagram","youtube","telegram"}){String url=str(s,k);if(!url.isEmpty())a.button(container,k.substring(0,1).toUpperCase(java.util.Locale.US)+k.substring(1)+" ↗",()->{try{android.net.Uri u=android.net.Uri.parse(url);if(!"https".equals(u.getScheme()))throw new Exception();a.startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception e){a.message("Social link must use HTTPS");}});}}).addOnFailureListener(e->a.note(container,"Social links unavailable: "+e.getMessage()));}
}
